import { Array, Effect } from "effect"

export interface Shipment {
  readonly trackingId: string
  readonly destination: string
  readonly status: "pending" | "ready" | "dispatched"
  readonly weightGrams: number
}

interface ManifestEntry {
  readonly trackingId: string
  readonly weightGrams: number
}

export const buildManifest = (
  shipments: ReadonlyArray<Shipment>,
  destination: string,
  generatedAt: string
) =>
  Effect.sync(() => {
    const ready = Array.filter(shipments,
      (shipment) => shipment.status === "ready" && shipment.destination === destination
    )
    const entries: ManifestEntry[] = []
    let totalWeightGrams = 0

    for (const shipment of ready) {
      entries.push({
        trackingId: shipment.trackingId,
        weightGrams: shipment.weightGrams
      })
      totalWeightGrams += shipment.weightGrams
    }

    return JSON.stringify({ destination, generatedAt, totalWeightGrams, entries })
  })
